UPLOAD_DIR = Path("./documents")
UPLOAD_DIR.mkdir(exist_ok=True)

METADATA_FILE = Path("./metadata.json")

API_KEY = os.getenv("LLM_API_KEY", "")
API_ENDPOINT = os.getenv("LLM_API_ENDPOINT", "")
MODEL_NAME = os.getenv("MODEL_NAME", "")

class QueryRequest(BaseModel):
    question: str
    top_k: int = 5

class Document:
    def __init__(self, doc_id: str, filename: str, content: str):
        self.doc_id = doc_id
        self.filename = filename
        self.content = content

def load_metadata():
    if METADATA_FILE.exists():
        with open(METADATA_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {}

def save_metadata(metadata):
    with open(METADATA_FILE, 'w', encoding='utf-8') as f:
        json.dump(metadata, f, ensure_ascii=False, indent=2)

def extract_text_from_pdf(file_path: Path) -> str:
    text = ""
    with open(file_path, 'rb') as f:
        reader = PyPDF2.PdfReader(f)
        for page in reader.pages:
            text += page.extract_text()
    return text

def extract_text_from_docx(file_path: Path) -> str:
    doc = docx.Document(file_path)
    return "\n".join([para.text for para in doc.paragraphs])

def extract_text_from_txt(file_path: Path) -> str:
    with open(file_path, 'r', encoding='utf-8') as f:
        return f.read()

def extract_text(file_path: Path) -> str:
    ext = file_path.suffix.lower()
    if ext == '.pdf':
        return extract_text_from_pdf(file_path)
    elif ext == '.docx':
        return extract_text_from_docx(file_path)
    elif ext in ['.txt', '.md']:
        return extract_text_from_txt(file_path)
    else:
        raise ValueError(f"Unsupported file type: {ext}")

def load_all_documents() -> List[Document]:
    metadata = load_metadata()
    documents = []
    for doc_id, info in metadata.items():
        file_path = UPLOAD_DIR / info['filename']
        if file_path.exists():
            try:
                content = extract_text(file_path)
                documents.append(Document(doc_id, info['filename'], content))
            except Exception:
                pass
    return documents

def search_documents(query: str, documents: List[Document], top_k: int = 5) -> List[Document]:
    if not documents:
        return []

    corpus = [doc.content for doc in documents]
    tokenized_corpus = [word_tokenize(doc.lower()) for doc in corpus]
    bm25 = BM25Okapi(tokenized_corpus)

    tokenized_query = word_tokenize(query.lower())
    scores = bm25.get_scores(tokenized_query)

    top_indices = sorted(range(len(scores)), key=lambda i: scores[i], reverse=True)[:top_k]

    return [documents[i] for i in top_indices if scores[i] > 0]

async def call_llm(prompt: str, context: str) -> str:
    full_prompt = f"Context:\n{context}\n\nQuestion: {prompt}\n\nAnswer based on the context provided:"

    async with httpx.AsyncClient(timeout=120.0) as client:
        headers = {
            "Authorization": f"Bearer {API_KEY}",
            "Content-Type": "application/json"
        }

        payload = {
            "model": MODEL_NAME,
            "messages": [
                {"role": "system", "content": "You are a helpful assistant that answers questions based on provided documents."},
                {"role": "user", "content": full_prompt}
            ],
            "temperature": 0.7,
            "max_tokens": 4000
        }

        response = await client.post(API_ENDPOINT, headers=headers, json=payload)
        response.raise_for_status()

        result = response.json()
        return result['choices'][0]['message']['content']

@app.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    if not file.filename:
        raise HTTPException(status_code=400, detail="No file provided")

    doc_id = str(uuid.uuid4())
    file_path = UPLOAD_DIR / file.filename

    content = await file.read()
    with open(file_path, 'wb') as f:
        f.write(content)

    metadata = load_metadata()
    metadata[doc_id] = {
        "filename": file.filename,
        "uploaded_at": str(Path(file_path).stat().st_mtime)
    }
    save_metadata(metadata)

    return JSONResponse({"doc_id": doc_id, "filename": file.filename})

@app.post("/query")
async def query_documents(request: QueryRequest):
    if not API_KEY or not API_ENDPOINT or not MODEL_NAME:
        raise HTTPException(status_code=500, detail="LLM API not configured")

    documents = load_all_documents()

    if not documents:
        raise HTTPException(status_code=404, detail="No documents found")

    relevant_docs = search_documents(request.question, documents, request.top_k)

    if not relevant_docs:
        raise HTTPException(status_code=404, detail="No relevant documents found")

    context = "\n\n".join([f"Document: {doc.filename}\n{doc.content[:50000]}" for doc in relevant_docs])

    answer = await call_llm(request.question, context)

    return JSONResponse({
        "answer": answer,
        "sources": [doc.filename for doc in relevant_docs]
    })

@app.get("/documents")
async def list_documents():
    metadata = load_metadata()
    return JSONResponse({"documents": [{"doc_id": k, **v} for k, v in metadata.items()]})

@app.delete("/documents/{doc_id}")
async def delete_document(doc_id: str):
    metadata = load_metadata()

    if doc_id not in metadata:
        raise HTTPException(status_code=404, detail="Document not found")

    filename = metadata[doc_id]['filename']
    file_path = UPLOAD_DIR / filename

    if file_path.exists():
        file_path.unlink()

    del metadata[doc_id]
    save_metadata(metadata)

    return JSONResponse({"status": "deleted", "doc_id": doc_id})

